import { afterAll, beforeAll, describe, expect, it } from "vitest";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as labelService from "@/server/services/label-service";
import { mergeLabelsSchema } from "@/schemas/label";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

describe("merge", () => {
  it("works", async () => {
    const t = await createTenant("mrg");
    const o = await createTenant("oth");
    const mk = (orgId: any, name: string) => labelRepo.insertLabel({ orgId, name, color: "#000000", description: null } as any);
    const bug = await mk(t.org.id, "bug");
    const defect = await mk(t.org.id, "defect");
    const other = await mk(o.org.id, "x");
    const i1 = await issueRepo.insertIssue({ ...issueInput(t.org.id, t.project.id), labelIds: [defect.id] } as any, t.userIds.owner as any);
    const i2 = await issueRepo.insertIssue({ ...issueInput(t.org.id, t.project.id), labelIds: [defect.id, bug.id] } as any, t.userIds.owner as any);
    const i3 = await issueRepo.insertIssue({ ...issueInput(t.org.id, t.project.id), labelIds: [bug.id] } as any, t.userIds.owner as any);
    const admin = t.actors.admin;
    await expect(labelService.mergeLabels(t.actors.member, { orgId: t.org.id, sourceLabelId: defect.id, targetLabelId: bug.id })).rejects.toThrow();
    await expect(labelService.mergeLabels(admin, { orgId: t.org.id, sourceLabelId: defect.id, targetLabelId: defect.id })).rejects.toThrow();
    await expect(labelService.mergeLabels(admin, { orgId: t.org.id, sourceLabelId: defect.id, targetLabelId: other.id })).rejects.toMatchObject({ code: "not_found" });
    expect((await labelRepo.listLabels(t.org.id)).length).toBe(2);
    const r = await labelService.mergeLabels(admin, { orgId: t.org.id, sourceLabelId: defect.id, targetLabelId: bug.id });
    expect(r.issuesRelabelled).toBe(2);
    expect(r.label.id).toBe(bug.id);
    const m = await labelRepo.listLabelsForIssues(t.org.id, [i1.id, i2.id, i3.id] as any);
